window.TASK_BANKS[65] = {"version":1,"topicId":65,"tasks":[{"id":"65.1","codeLang":"python","answer":"<h1>&lt;A&amp;B&gt;</h1>","answerLang":"text","explanation":"Код шаблона создаёт h1, а значение title экранируется отдельно. Пользовательская строка не проходит второй рендеринг.","verified":"3.14","wrong":["<h1><A&B></h1>","&lt;h1&gt;&lt;A&amp;B&gt;&lt;/h1&gt;","<h1>{{ title }}</h1>"]},{"id":"65.2","codeLang":"python","answer":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\ndef render_greeting(name):\n    env=Environment(autoescape=True)\n    return env.from_string('<p>Привет, {{ name }}!</p>').render(name=name)","answerLang":"python","explanation":"Доверенный шаблон постоянен, входная строка — только значение контекста. Конкатенация name с исходником шаблона нарушила бы эту границу.","verified":"3.14","check":{"append":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\nfrom bs4 import BeautifulSoup\nfrom copy import deepcopy\ndef _fails(error,fn,*args):\n    try:fn(*args)\n    except error:return\n    raise AssertionError('Не скрывайте ошибку шаблона успешной пустой строкой')\ndef _html(value):\n    assert type(value) is str, 'Верните строку HTML'\n    parsed=BeautifulSoup(value,'html.parser')\n    assert not parsed.find(['script','img','iframe']), 'Данные должны оставаться текстом'\n    return parsed\nfor name in ['Мира','<script>alert(1)</script>','A & B','{{ 2+3 }}','']:\n    root=_html(render_greeting(name));paragraph=root.find('p')\n    assert paragraph and paragraph.get_text()=='Привет, '+name+'!', 'Не исполняйте и не теряйте текст данных'\n    assert len(root.find_all('p'))==1 and not paragraph.find(True), 'Внутри приветствия не должно появиться тегов из данных'\nprint('OK')","expect":"OK"}},{"id":"65.3","codeLang":"python","answer":"Пока пусто","answerLang":"text","explanation":"В Jinja блок else у for выполняется, если цикл не вывел ни одного элемента. Он помогает явно показать пустые данные.","verified":"3.14","wrong":["None","[]"]},{"id":"65.4","codeLang":"python","answer":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\ndef count_label(count):\n    return Environment(autoescape=True).from_string('{{ \"нет данных\" if value is none else value }}').render(value=count)","answerLang":"python","explanation":"default(...,true) заменяет все ложные значения, включая 0. Когда отсутствие обозначено None, проверяйте именно его.","verified":"3.14","check":{"append":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\nfrom bs4 import BeautifulSoup\nfrom copy import deepcopy\ndef _fails(error,fn,*args):\n    try:fn(*args)\n    except error:return\n    raise AssertionError('Не скрывайте ошибку шаблона успешной пустой строкой')\ndef _html(value):\n    assert type(value) is str, 'Верните строку HTML'\n    parsed=BeautifulSoup(value,'html.parser')\n    assert not parsed.find(['script','img','iframe']), 'Данные должны оставаться текстом'\n    return parsed\nfor value,expected in [(None,'нет данных'),(0,'0'),(7,'7'),(-2,'-2')]:\n    assert count_label(value)==expected, 'Не смешивайте ноль с отсутствием данных'\nprint('OK')","expect":"OK"}},{"id":"65.5","codeLang":"python","answer":"0","answerLang":"text","explanation":"Присваивание внутри цикла не изменяет внешнюю переменную. Обычный числовой итог проще вычислить в Python и передать через контекст. Для осознанного состояния шаблона есть namespace, но он здесь не нужен.","verified":"3.14","wrong":["12","7","Ошибка"]},{"id":"65.6","codeLang":"python","answer":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\ndef render_names(names):\n    text='<ul>{% for name in names %}<li>{{ name }}</li>{% else %}<li class=\"empty\">Нет имён</li>{% endfor %}</ul>'\n    return Environment(autoescape=True).from_string(text).render(names=names)","answerLang":"python","explanation":"Цикл создаёт разметку, а autoescape действует для каждого значения. Пустая строка внутри списка — полноценное имя для этого контракта, а не повод удалить элемент.","verified":"3.14","check":{"append":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\nfrom bs4 import BeautifulSoup\nfrom copy import deepcopy\ndef _fails(error,fn,*args):\n    try:fn(*args)\n    except error:return\n    raise AssertionError('Не скрывайте ошибку шаблона успешной пустой строкой')\ndef _html(value):\n    assert type(value) is str, 'Верните строку HTML'\n    parsed=BeautifulSoup(value,'html.parser')\n    assert not parsed.find(['script','img','iframe']), 'Данные должны оставаться текстом'\n    return parsed\nfor names in [['Оля','<b>имя</b>','A&B',''],[]]:\n    before=list(names);root=_html(render_names(names));items=root.select('ul > li')\n    if names:\n        assert [li.get_text() for li in items]==names, 'Сохраните порядок и пустые строки'\n        assert all(not li.find(True) for li in items), 'Имена не должны создавать разметку'\n    else:assert len(items)==1 and items[0].get('class')==['empty'] and items[0].get_text()=='Нет имён', 'Покажите пустой список явно'\n    assert names==before, 'Не меняйте входной список'\nprint('OK')","expect":"OK"}},{"id":"65.7","codeLang":"python","answer":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\ndef render_person(data):\n    env=Environment(autoescape=True,undefined=StrictUndefined)\n    return env.from_string('Имя: {{ name }}').render(data)","answerLang":"python","explanation":"Обычный Undefined часто превращается в пустую строку. StrictUndefined делает отсутствующее обязательное значение видимой ошибкой; это не полноценная проверка типов входных данных.","verified":"3.14","check":{"append":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\nfrom bs4 import BeautifulSoup\nfrom copy import deepcopy\ndef _fails(error,fn,*args):\n    try:fn(*args)\n    except error:return\n    raise AssertionError('Не скрывайте ошибку шаблона успешной пустой строкой')\ndef _html(value):\n    assert type(value) is str, 'Верните строку HTML'\n    parsed=BeautifulSoup(value,'html.parser')\n    assert not parsed.find(['script','img','iframe']), 'Данные должны оставаться текстом'\n    return parsed\nassert render_person({'name':'Лена'})=='Имя: Лена'\nassert render_person({'name':''})=='Имя: '\n_fails(UndefinedError,render_person,{})\nprint('OK')","expect":"OK"}},{"id":"65.8","codeLang":"python","answer":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\ndef render_badges(labels):\n    text='{% macro badge(text) %}<span class=\"badge\">{{ text }}</span>{% endmacro %}<div>{% for text in labels %}{{ badge(text) }}{% endfor %}</div>'\n    return Environment(autoescape=True).from_string(text).render(labels=labels)","answerLang":"python","explanation":"Макрос повторяет доверенную разметку и экранирует свой аргумент внутри неё. Не нужно помечать входные строки фильтром safe.","verified":"3.14","check":{"append":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\nfrom bs4 import BeautifulSoup\nfrom copy import deepcopy\ndef _fails(error,fn,*args):\n    try:fn(*args)\n    except error:return\n    raise AssertionError('Не скрывайте ошибку шаблона успешной пустой строкой')\ndef _html(value):\n    assert type(value) is str, 'Верните строку HTML'\n    parsed=BeautifulSoup(value,'html.parser')\n    assert not parsed.find(['script','img','iframe']), 'Данные должны оставаться текстом'\n    return parsed\nfor labels in [['new','<b>x</b>','A&B'],[]]:\n    root=_html(render_badges(labels));badges=root.select('div > span.badge')\n    assert [b.get_text() for b in badges]==labels and all(not b.find(True) for b in badges), 'Проверьте отдельные метки и экранирование'\nprint('OK')","expect":"OK"}},{"id":"65.9","codeLang":"python","answer":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\n\ndef render_catalog(rows,title):\n    templates={\n        'base.html':'<!doctype html><html><head><title>{{ title }}</title></head><body><h1>{{ title }}</h1>{% block body %}{% endblock %}</body></html>',\n        'catalog.html':'{% extends \"base.html\" %}{% block body %}<ul class=\"products\">{% for row in rows %}<li class=\"product\"><span class=\"name\">{{ row[\"name\"] }}</span><span class=\"qty\">{{ row[\"qty\"] }}</span></li>{% else %}<li class=\"empty\">Нет товаров</li>{% endfor %}</ul>{% endblock %}',\n    }\n    env=Environment(loader=DictLoader(templates),autoescape=select_autoescape(),undefined=StrictUndefined)\n    return env.get_template('catalog.html').render(rows=rows,title=title)","answerLang":"python","explanation":"Общий каркас и дочерний шаблон собираются через loader и block. Данные остаются контекстом, ноль выводится как ноль, а StrictUndefined останавливает рендеринг при пропуске обязательного поля.","verified":"3.14","hint":"Проверьте отчёт как HTML-дерево: отдельные строки, нулевой остаток и имя, похожее на тег. Повторите с пустыми данными и пропущенным полем.","check":{"append":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\nfrom bs4 import BeautifulSoup\nfrom copy import deepcopy\ndef _fails(error,fn,*args):\n    try:fn(*args)\n    except error:return\n    raise AssertionError('Не скрывайте ошибку шаблона успешной пустой строкой')\ndef _html(value):\n    assert type(value) is str, 'Верните строку HTML'\n    parsed=BeautifulSoup(value,'html.parser')\n    assert not parsed.find(['script','img','iframe']), 'Данные должны оставаться текстом'\n    return parsed\nrows=[{'name':'A & B','qty':0},{'name':'<script>bad()</script>','qty':7},{'name':'{{ 6*7 }}','qty':2}]\nbefore=deepcopy(rows);title='<b>Остатки</b> & склад'\nroot=_html(render_catalog(rows,title))\nassert root.title and root.title.get_text()==title and root.h1 and root.h1.get_text()==title, 'Сохраните и экранируйте заголовок'\nitems=root.select('ul.products > li.product')\nassert len(items)==3, 'Нужна отдельная запись для каждой строки'\nassert [x.select_one('.name').get_text() for x in items]==[r['name'] for r in rows], 'Сохраните порядок и буквальный текст имени'\nassert [x.select_one('.qty').get_text() for x in items]==['0','7','2'], 'Не подменяйте нулевой остаток'\nassert all(not x.select_one('.name').find(True) for x in items), 'Имя не должно создавать теги'\nassert rows==before, 'Входные данные должны остаться прежними'\nempty=_html(render_catalog([],'Пусто'));placeholder=empty.select('ul.products > li.empty')\nassert len(placeholder)==1 and placeholder[0].get_text()=='Нет товаров' and not empty.select('li.product'), 'Нужен понятный пустой каталог'\n_fails(UndefinedError,render_catalog,[{'name':'x'}],'X')\n_fails(UndefinedError,render_catalog,[{'qty':1}],'X')\nprint('OK')","expect":"OK"}},{"id":"65.10","codeLang":"python","answer":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\n\ndef make_renderer(templates):\n    env=Environment(loader=DictLoader(dict(templates)),autoescape=select_autoescape(),undefined=StrictUndefined)\n    def render(name,context):\n        return env.get_template(name).render(context)\n    return render","answerLang":"python","explanation":"Глобальный Environment смешивал шаблоны двух отчётов и скрывал ошибки. Отдельный loader со снимком словаря отделяет настройки и кэш; select_autoescape выбирает поведение по расширению.","verified":"3.14","hint":"Создайте две фабрики с одинаковым именем шаблона и разным содержимым. Проверьте их по очереди, затем измените исходный словарь и вызовите ошибочные варианты.","check":{"append":"from jinja2 import Environment, DictLoader, StrictUndefined, UndefinedError, TemplateNotFound, select_autoescape\nfrom bs4 import BeautifulSoup\nfrom copy import deepcopy\ndef _fails(error,fn,*args):\n    try:fn(*args)\n    except error:return\n    raise AssertionError('Не скрывайте ошибку шаблона успешной пустой строкой')\ndef _html(value):\n    assert type(value) is str, 'Верните строку HTML'\n    parsed=BeautifulSoup(value,'html.parser')\n    assert not parsed.find(['script','img','iframe']), 'Данные должны оставаться текстом'\n    return parsed\ntemplates={'card.html':'<b>{{ value }}</b>','note.txt':'{{ value }}','caps.HTML':'<i>{{ value }}</i>','item.xml':'<item>{{ value }}</item>'}\nbefore=deepcopy(templates);a=make_renderer(templates)\nb=make_renderer({'card.html':'<em>{{ value }}</em>'})\ncontext={'value':'<A&B>'};saved=deepcopy(context)\nfor render,tag in [(a,'b'),(b,'em'),(a,'b')]:\n    root=_html(render('card.html',context));node=root.find(tag)\n    assert node and node.get_text()==context['value'] and not node.find(True), 'Фабрики должны быть независимы, а значения экранированы'\nassert a('note.txt',context)=='<A&B>', 'Для txt нужен обычный текст'\nassert _html(a('caps.HTML',context)).i.get_text()=='<A&B>', 'Расширение проверяется без учёта регистра'\nassert '&lt;A&amp;B&gt;' in a('item.xml',context), 'XML тоже требует экранирования'\nassert templates==before and context==saved, 'Не меняйте входные словари'\ntemplates['card.html']='<p>changed</p>'\nnode=_html(a('card.html',context)).b\nassert node is not None and node.get_text()=='<A&B>', 'Снимок шаблонов не должен следить за внешней мутацией'\n_fails(TemplateNotFound,a,'missing.html',context)\n_fails(UndefinedError,a,'card.html',{})\nassert _html(b('card.html',context)).em.get_text()=='<A&B>', 'Ошибка одной фабрики не меняет другую'\nprint('OK')","expect":"OK"}}]};
